import {IStandardExchangeIn} from "@crane/contracts/interfaces/IStandardExchangeIn.sol";
import {IStandardExchangeOut} from "@crane/contracts/interfaces/IStandardExchangeOut.sol";

import {
    TestBase_UniswapV4StandardExchangeOrbitalBufferHook as TestBase
} from "contracts/hooks/uniswap/v4/standardExchange/orbital/TestBase_UniswapV4StandardExchangeOrbitalBufferHook.sol";
import {
    IUniswapV4StandardExchangeOrbitalBufferHook as IHook
} from "contracts/hooks/uniswap/v4/standardExchange/orbital/interfaces/IUniswapV4StandardExchangeOrbitalBufferHook.sol";
import {IUniswapV4SeBufferHook} from "contracts/hooks/uniswap/v4/interfaces/IUniswapV4SeBufferHook.sol";
import {IDetfReserveQuote} from "contracts/hooks/uniswap/v4/interfaces/IDetfReserveQuote.sol";
import {
    UniswapV4StandardExchangeOrbitalBufferHook_FactoryService as PkgFactory
} from "contracts/hooks/uniswap/v4/standardExchange/orbital/UniswapV4StandardExchangeOrbitalBufferHook_FactoryService.sol";

/**
 * @title UniswapV4StandardExchangeOrbitalBufferHook_Surface_Test
 * @notice WP-J-HOOK-001: Target ⊆ facetFuncs ⊆ loupe ⊆ **proxy** smoke for SE orbital buffer (sebuf).
 */
contract UniswapV4StandardExchangeOrbitalBufferHook_Surface_Test is TestBase {
    IFacet internal hooksFacet;
    IFacet internal depositFacet;
    IFacet internal depositQueryFacet;
    IFacet internal depositZapFacet;
    IFacet internal withdrawFacet;
    IFacet internal seFacet;

    function setUp() public override {
        super.setUp();
        hooksFacet = PkgFactory.deployHooksFacet(create3Factory);
        depositFacet = PkgFactory.deployDepositFacet(create3Factory);
        depositQueryFacet = hookPkg.DEPOSIT_QUERY_FACET();
        depositZapFacet = hookPkg.DEPOSIT_ZAP_FACET();
        withdrawFacet = PkgFactory.deployWithdrawFacet(create3Factory);
        seFacet = PkgFactory.deploySeFacet(create3Factory);
    }

    function _contains(bytes4[] memory funcs_, bytes4 sel_) internal pure returns (bool) {
        for (uint256 i; i < funcs_.length; ++i) {
            if (funcs_[i] == sel_) return true;
        }
        return false;
    }

    function _assertFacetFuncsOnLoupe(IFacet facet_, address expectedFacet_) internal view {
        bytes4[] memory funcs_ = facet_.facetFuncs();
        IDiamondLoupe loupe_ = IDiamondLoupe(hook);
        for (uint256 i; i < funcs_.length; ++i) {
            address loupeFacet_ = loupe_.facetAddress(funcs_[i]);
            assertEq(loupeFacet_, expectedFacet_, "J2 loupe maps selector to CREATE3 facet");
            assertTrue(loupeFacet_ != address(0), "J2 not zero");
            assertTrue(loupeFacet_ != hook, "J2 not self-facet");
        }
    }

    /* ---------------------------------------------------------------------- */
    /*  J1: Target / interface money+view selectors ⊆ facetFuncs             */
    /* ---------------------------------------------------------------------- */

    function test_J1_hooks_targetSelectors_subseteq_facetFuncs() public view {
        bytes4[] memory funcs_ = hooksFacet.facetFuncs();
        assertTrue(_contains(funcs_, IHooks.beforeSwap.selector), "J1 beforeSwap");
        assertTrue(_contains(funcs_, IHooks.beforeInitialize.selector), "J1 beforeInitialize");
        assertTrue(_contains(funcs_, IHooks.beforeAddLiquidity.selector), "J1 beforeAddLiquidity");
        assertTrue(_contains(funcs_, IHook.poolManager.selector), "J1 poolManager");
        assertTrue(_contains(funcs_, IHook.token0.selector), "J1 token0");
        assertTrue(_contains(funcs_, IHook.token1.selector), "J1 token1");
        assertTrue(_contains(funcs_, IHook.token2.selector), "J1 token2");
        assertTrue(_contains(funcs_, IHook.standardExchange.selector), "J1 standardExchange");
        assertTrue(_contains(funcs_, IHook.isBuffered.selector), "J1 isBuffered");
        assertTrue(_contains(depositQueryFacet.facetFuncs(), IHook.radius.selector), "J1 radius query");
        assertTrue(_contains(funcs_, IHook.rawReserve.selector), "J1 rawReserve");
        assertTrue(_contains(funcs_, IHook.seClaim.selector), "J1 seClaim");
        assertTrue(_contains(funcs_, IHook.effectiveReserve.selector), "J1 effectiveReserve");
        assertTrue(_contains(funcs_, IUniswapV4SeBufferHook.previewSwapExactIn.selector), "J1 previewSwapExactIn");
        assertTrue(_contains(funcs_, IUniswapV4SeBufferHook.previewSwapExactOut.selector), "J1 previewSwapExactOut");
        assertTrue(_contains(funcs_, IUniswapV4SeBufferHook.tokens.selector), "J1 tokens");
        assertTrue(_contains(funcs_, IUniswapV4SeBufferHook.isLive.selector), "J1 isLive");
        assertTrue(_contains(funcs_, IUniswapV4SeBufferHook.firstJoinMustBeFullBook.selector), "J1 firstJoinMustBeFullBook");
        assertEq(funcs_.length, 46, "J1 HooksFacet facetFuncs length");
    }

    function test_J1_deposit_targetSelectors_subseteq_facetFuncs() public view {
        bytes4[] memory funcs_ = depositFacet.facetFuncs();
        bytes4[] memory queries_ = depositQueryFacet.facetFuncs();
        bytes4[] memory zaps_ = depositZapFacet.facetFuncs();
        assertTrue(_contains(funcs_, IHook.addLiquidity.selector), "J1 addLiquidity");
        assertTrue(_contains(zaps_, IHook.depositSingle.selector), "J1 depositSingle");
        assertTrue(_contains(queries_, IHook.previewAddLiquidity.selector), "J1 previewAddLiquidity");
        assertTrue(_contains(queries_, IHook.previewDepositSingle.selector), "J1 previewDepositSingle");
        assertTrue(_contains(queries_, IHook.previewZapSplit.selector), "J1 previewZapSplit");
        assertTrue(_contains(funcs_, IHook.depositFlexible.selector), "J1 depositFlexible");
        assertTrue(_contains(queries_, IHook.previewDepositFlexible.selector), "J1 previewDepositFlexible");
        assertTrue(_contains(funcs_, IUniswapV4SeBufferHook.joinUnbalanced.selector), "J1 joinUnbalanced");
        assertTrue(_contains(zaps_, IUniswapV4SeBufferHook.joinSingleAssetExactIn.selector), "J1 joinSingleAssetExactIn");
        assertEq(funcs_.length, 4, "J1 deposit execution selectors");
        assertEq(queries_.length, 11, "J1 deposit query selectors");
        assertEq(zaps_.length, 3, "J1 deposit zap selectors");
    }

    function test_J1_withdraw_targetSelectors_subseteq_facetFuncs() public view {
        bytes4[] memory funcs_ = withdrawFacet.facetFuncs();
        assertTrue(_contains(funcs_, IHook.removeLiquidity.selector), "J1 removeLiquidity");
        assertTrue(_contains(funcs_, IHook.previewRemoveLiquidity.selector), "J1 previewRemoveLiquidity");
        assertTrue(_contains(funcs_, IHook.withdrawFlexible.selector), "J1 withdrawFlexible");
        assertTrue(_contains(funcs_, IHook.previewWithdrawFlexible.selector), "J1 previewWithdrawFlexible");
        assertTrue(_contains(funcs_, IUniswapV4SeBufferHook.exitProportional.selector), "J1 exitProportional");
        assertTrue(_contains(funcs_, IDetfReserveQuote.previewBurnToToken.selector), "J1 previewBurnToToken");
        assertEq(funcs_.length, 11, "J1 WithdrawFacet facetFuncs length");
    }

    function test_J1_se_targetSelectors_subseteq_facetFuncs() public view {
        bytes4[] memory funcs_ = seFacet.facetFuncs();
        assertTrue(_contains(funcs_, IStandardExchangeIn.previewExchangeIn.selector), "J1 previewExchangeIn");
        assertTrue(_contains(funcs_, IStandardExchangeIn.exchangeIn.selector), "J1 exchangeIn");
        assertTrue(_contains(funcs_, IStandardExchangeOut.previewExchangeOut.selector), "J1 previewExchangeOut");
        assertTrue(_contains(funcs_, IStandardExchangeOut.exchangeOut.selector), "J1 exchangeOut");
        assertTrue(_contains(funcs_, IUniswapV4SeBufferHook.ownerSwapExactIn.selector), "J1 ownerSwapExactIn");
        assertTrue(_contains(funcs_, IUniswapV4SeBufferHook.ownerSwapExactOut.selector), "J1 ownerSwapExactOut");
        assertTrue(_contains(funcs_, IStandardizedYield.deposit.selector), "J1 SY deposit");
        assertTrue(_contains(funcs_, IStandardizedYield.redeem.selector), "J1 SY redeem");
        assertTrue(_contains(funcs_, IStandardizedYield.exchangeRate.selector), "J1 SY exchangeRate");
        assertTrue(_contains(funcs_, IStandardizedYield.yieldToken.selector), "J1 SY yieldToken");
        assertTrue(_contains(funcs_, IStandardizedYield.assetInfo.selector), "J1 SY assetInfo");
        assertTrue(_contains(funcs_, IStandardizedYield.getTokensIn.selector), "J1 SY getTokensIn");
        assertTrue(_contains(funcs_, IStandardizedYield.getTokensOut.selector), "J1 SY getTokensOut");
        assertTrue(_contains(funcs_, IStandardizedYield.isValidTokenIn.selector), "J1 SY isValidTokenIn");
        assertTrue(_contains(funcs_, IStandardizedYield.isValidTokenOut.selector), "J1 SY isValidTokenOut");
        assertTrue(_contains(funcs_, IStandardizedYield.previewDeposit.selector), "J1 SY previewDeposit");
        assertTrue(_contains(funcs_, IStandardizedYield.previewRedeem.selector), "J1 SY previewRedeem");
        assertTrue(_contains(funcs_, IStandardizedYield.getRewardTokens.selector), "J1 SY getRewardTokens");
        assertTrue(_contains(funcs_, IStandardizedYield.accruedRewards.selector), "J1 SY accruedRewards");
        assertTrue(_contains(funcs_, IStandardizedYield.rewardIndexesCurrent.selector), "J1 SY rewardIndexesCurrent");
        assertTrue(_contains(funcs_, IStandardizedYield.rewardIndexesStored.selector), "J1 SY rewardIndexesStored");
        assertTrue(_contains(funcs_, IStandardizedYield.claimRewards.selector), "J1 SY claimRewards");
        assertEq(funcs_.length, 22, "J1 SeFacet facetFuncs length");
    }

    /* ---------------------------------------------------------------------- */
    /*  J2: facetFuncs ⊆ loupe on production hook proxy                      */
    /* ---------------------------------------------------------------------- */

    function test_J2_hooks_facetFuncs_subseteq_loupe_onProxy() public view {
        _assertFacetFuncsOnLoupe(hooksFacet, address(hooksFacet));
    }

    function test_J2_deposit_facetFuncs_subseteq_loupe_onProxy() public view {
        _assertFacetFuncsOnLoupe(depositFacet, address(depositFacet));
        _assertFacetFuncsOnLoupe(depositQueryFacet, address(depositQueryFacet));
        _assertFacetFuncsOnLoupe(depositZapFacet, address(depositZapFacet));
    }

    function test_J2_withdraw_facetFuncs_subseteq_loupe_onProxy() public view {
        _assertFacetFuncsOnLoupe(withdrawFacet, address(withdrawFacet));
    }

    function test_J2_se_facetFuncs_subseteq_loupe_onProxy() public view {
        _assertFacetFuncsOnLoupe(seFacet, address(seFacet));
    }

    /* ---------------------------------------------------------------------- */
    /*  J3: proxy smoke — loupe-routed calls (not facet impl address)        */
    /* ---------------------------------------------------------------------- */

    function test_J3_proxySmoke_bindingAndReserveViews() public view {
        IHook proxy_ = orbital;
        IDiamondLoupe loupe_ = IDiamondLoupe(hook);

        assertEq(address(proxy_.poolManager()), address(pm), "J3 poolManager on proxy");
        assertEq(proxy_.token0(), address(token0), "J3 token0 on proxy");
        assertEq(proxy_.token1(), address(token1), "J3 token1 on proxy");
        assertEq(proxy_.token2(), address(token2), "J3 token2 on proxy");
        assertEq(proxy_.standardExchange(0), se0, "J3 se0 on proxy");
        assertTrue(proxy_.isBuffered(0), "J3 leg0 buffered");
        assertEq(proxy_.radius(), 0, "J3 inert radius");
        assertEq(proxy_.rawReserve(0), 0, "J3 inert rawReserve0");
        assertEq(proxy_.seClaim(0), 0, "J3 inert seClaim0");

        address loupeHooks_ = loupe_.facetAddress(IHook.radius.selector);
        assertEq(loupeHooks_, address(depositQueryFacet), "J3 radius loupe");
        assertTrue(loupeHooks_ != hook, "J3 not self-facet");

        address loupeDep_ = loupe_.facetAddress(IHook.addLiquidity.selector);
        assertEq(loupeDep_, address(depositFacet), "J3 addLiquidity loupe");

        address loupeWd_ = loupe_.facetAddress(IHook.removeLiquidity.selector);
        assertEq(loupeWd_, address(withdrawFacet), "J3 removeLiquidity loupe");

        address loupeSe_ = loupe_.facetAddress(IStandardExchangeIn.exchangeIn.selector);
        assertEq(loupeSe_, address(seFacet), "J3 se exchangeIn loupe");
    }

    function test_J_facetMetadata_hooks_matches_CREATE3_facet() public view {
        (string memory name_, bytes4[] memory ifaces_, bytes4[] memory funcs_) = hooksFacet.facetMetadata();
        assertEq(
            keccak256(bytes(name_)),
            keccak256(bytes("UniswapV4StandardExchangeOrbitalBufferHookHooksFacet"))
        );
        assertTrue(ifaces_.length >= 1, "J interfaces");
        assertEq(hooksFacet.facetFuncs().length, funcs_.length);
        assertEq(keccak256(abi.encodePacked(funcs_)), keccak256(abi.encodePacked(hooksFacet.facetFuncs())));
    }

    function test_J_facetMetadata_deposit_matches_CREATE3_facet() public view {
        (string memory name_,, bytes4[] memory funcs_) = depositFacet.facetMetadata();
        assertEq(
            keccak256(bytes(name_)),
            keccak256(bytes("UniswapV4StandardExchangeOrbitalBufferHookDepositFacet"))
        );
        assertEq(depositFacet.facetFuncs().length, funcs_.length);
        assertEq(keccak256(abi.encodePacked(funcs_)), keccak256(abi.encodePacked(depositFacet.facetFuncs())));
    }

    function test_J_facetMetadata_se_matches_CREATE3_facet() public view {
        (string memory name_, bytes4[] memory ifaces_, bytes4[] memory funcs_) = seFacet.facetMetadata();
        assertEq(keccak256(bytes(name_)), keccak256(bytes("UniswapV4StandardExchangeOrbitalBufferHookSeFacet")));
        assertTrue(ifaces_.length >= 2, "J SE interfaces");
        assertEq(seFacet.facetFuncs().length, funcs_.length);
        assertEq(keccak256(abi.encodePacked(funcs_)), keccak256(abi.encodePacked(seFacet.facetFuncs())));
    }
}

// SPDX-License-Identifier: BSL-1.1
pragma solidity ^0.8.0;

import {IERC20} from "@crane/contracts/interfaces/IERC20.sol";
import {IERC165} from "@crane/contracts/interfaces/IERC165.sol";
import {IFacet} from "@crane/contracts/interfaces/IFacet.sol";
import {IDiamond} from "@crane/contracts/interfaces/IDiamond.sol";
import {IDiamondLoupe} from "@crane/contracts/interfaces/IDiamondLoupe.sol";
import {IHooks} from "@crane/contracts/protocols/dexes/uniswap/v4/interfaces/IHooks.sol";
import {PoolKey} from "@crane/contracts/protocols/dexes/uniswap/v4/types/PoolKey.sol";
import {Currency} from "@crane/contracts/protocols/dexes/uniswap/v4/types/Currency.sol";
import {PoolId, PoolIdLibrary} from "@crane/contracts/protocols/dexes/uniswap/v4/types/PoolId.sol";
import {TickMath} from "@crane/contracts/protocols/dexes/uniswap/v4/libraries/TickMath.sol";
import {Proxy} from "@crane/contracts/proxies/Proxy.sol";
import {IStandardExchangeIn} from "@crane/contracts/interfaces/IStandardExchangeIn.sol";
import {Vm} from "forge-std/Vm.sol";

import {IStandardVault} from "contracts/interfaces/IStandardVault.sol";
import {IBasicVault} from "contracts/interfaces/IBasicVault.sol";
import {SimpleMintableERC20} from "contracts/test/stubs/SimpleMintableERC20.sol";
import {SimpleYieldERC4626} from "contracts/test/stubs/SimpleYieldERC4626.sol";
import {
    TestBase_UniswapV4StandardExchangeWeightedBufferHook
} from "test/foundry/spec/hooks/uniswap/v4/standardExchange/weighted/TestBase_UniswapV4StandardExchangeWeightedBufferHook.sol";
import {
    IUniswapV4StandardExchangeWeightedBufferHook
} from "contracts/hooks/uniswap/v4/standardExchange/weighted/interfaces/IUniswapV4StandardExchangeWeightedBufferHook.sol";
import {
    IUniswapV4HookStagedPairInit
} from "contracts/hooks/uniswap/v4/interfaces/IUniswapV4HookStagedPairInit.sol";
import {
    IUniswapV4StandardExchangeWeightedBufferHookPackage
} from "contracts/hooks/uniswap/v4/standardExchange/weighted/interfaces/IUniswapV4StandardExchangeWeightedBufferHookPackage.sol";
import {
    UniswapV4StandardExchangeWeightedBufferHookPairPoolLib as PairPoolLib
} from "contracts/hooks/uniswap/v4/standardExchange/weighted/UniswapV4StandardExchangeWeightedBufferHookPairPoolLib.sol";
import {
    UniswapV4StandardExchangeWeightedBufferHookTarget
} from "contracts/hooks/uniswap/v4/standardExchange/weighted/UniswapV4StandardExchangeWeightedBufferHookTarget.sol";

/**
 * @title UniswapV4StandardExchangeWeightedBufferHook_StagedInit_Test
 * @notice S43 bootstrap-only deploy plus door / finalize / J-surface matrix (n=2 and n>=3).
 */
contract UniswapV4StandardExchangeWeightedBufferHook_StagedInit_Test is
    TestBase_UniswapV4StandardExchangeWeightedBufferHook
{
    using PoolIdLibrary for PoolKey;

    bytes32 internal constant PAIR_POOL_DEPLOYED_TOPIC =
        keccak256("PairPoolDeployed(address,address,address,bytes32)");

    function test_S58_pkgFacetFuncs_exactlySix() public view {
        bytes4[] memory funcs = IFacet(address(hookPkg)).facetFuncs();
        assertEq(funcs.length, 6);
        assertEq(funcs[0], IHooks.beforeInitialize.selector);
        assertEq(funcs[1], IUniswapV4HookStagedPairInit.deployPair.selector);
        assertEq(funcs[2], IUniswapV4HookStagedPairInit.finalizeInitialization.selector);
        assertEq(funcs[3], IUniswapV4HookStagedPairInit.isPairPoolLive.selector);
        assertEq(funcs[4], IUniswapV4HookStagedPairInit.pairPoolKey.selector);
        assertEq(funcs[5], IUniswapV4HookStagedPairInit.isInitializationFinalized.selector);
    }

    function test_S43_deployAlone_noProductDoors() public {
        (address h, IUniswapV4HookStagedPairInit init, address[] memory toks) = _freshBootstrapN(2);
        assertFalse(init.isPairPoolLive(toks[0], toks[1]));
        assertFalse(init.isInitializationFinalized());
        assertTrue(h != address(0));
    }

    function test_S43_deployAlone_vaultConfigWorks() public {
        (address h,,) = _freshBootstrapN(2);
        IStandardVault(h).vaultConfig();
        assertTrue(_registry().isVault(h));
    }

    function test_S43_deployAlone_initSelectorsExist() public {
        (address h,,) = _freshBootstrapN(2);
        IDiamondLoupe loupe = IDiamondLoupe(h);
        assertEq(
            loupe.facetAddress(IUniswapV4HookStagedPairInit.deployPair.selector), address(hookPkg)
        );
        assertEq(
            loupe.facetAddress(IUniswapV4HookStagedPairInit.finalizeInitialization.selector),
            address(hookPkg)
        );
        assertEq(loupe.facetAddress(IHooks.beforeInitialize.selector), address(hookPkg));
        assertEq(
            loupe.facetAddress(IUniswapV4HookStagedPairInit.isPairPoolLive.selector), address(hookPkg)
        );
        assertEq(
            loupe.facetAddress(IUniswapV4HookStagedPairInit.pairPoolKey.selector), address(hookPkg)
        );
        assertEq(
            loupe.facetAddress(IUniswapV4HookStagedPairInit.isInitializationFinalized.selector),
            address(hookPkg)
        );
    }

    function test_S43_deployAlone_productionSelectorsUnmatched() public {
        (address h,,) = _freshBootstrapN(2);
        IDiamondLoupe loupe = IDiamondLoupe(h);
        assertEq(
            loupe.facetAddress(IUniswapV4StandardExchangeWeightedBufferHook.joinProportional.selector),
            address(0)
        );
        assertEq(
            loupe.facetAddress(IUniswapV4StandardExchangeWeightedBufferHook.exitProportional.selector),
            address(0)
        );
        assertEq(
            loupe.facetAddress(IUniswapV4StandardExchangeWeightedBufferHook.tokens.selector),
            address(0)
        );
        assertEq(loupe.facetAddress(IERC20.transfer.selector), address(0));
        assertEq(loupe.facetAddress(IHooks.beforeSwap.selector), address(0));
        assertEq(loupe.facetAddress(IStandardExchangeIn.exchangeIn.selector), address(0));
    }

    function test_S43_deployAlone_erc165_claimsIERC20() public {
        (address h,,) = _freshBootstrapN(2);
        assertTrue(IERC165(h).supportsInterface(type(IERC20).interfaceId));
        assertEq(IDiamondLoupe(h).facetAddress(IERC20.transfer.selector), address(0));
    }

    function test_S43_pairPoolKey_alwaysConstructed() public {
        (address h, IUniswapV4HookStagedPairInit init, address[] memory toks) = _freshBootstrapN(2);
        PoolKey memory expected =
            PairPoolLib.pairKey(toks[0], toks[1], PairPoolLib.TICK_SPACING, IHooks(h));
        PoolKey memory actual = init.pairPoolKey(toks[0], toks[1]);
        _assertKeyEq(actual, expected);
        _assertKeyEq(init.pairPoolKey(toks[1], toks[0]), actual);
        assertFalse(init.isPairPoolLive(toks[0], toks[1]));
    }

    function test_deployPair_emitsOnce() public {
        (address h, IUniswapV4HookStagedPairInit init, address[] memory toks) = _freshBootstrapN(2);
        (address c0, address c1) = toks[0] < toks[1] ? (toks[0], toks[1]) : (toks[1], toks[0]);
        PoolKey memory key = init.pairPoolKey(toks[0], toks[1]);
        bytes32 poolId = PoolId.unwrap(key.toId());
        vm.expectEmit(true, true, true, true, h);
        emit IUniswapV4HookStagedPairInit.PairPoolDeployed(h, c0, c1, poolId);
        PoolKey memory returned = init.deployPair(toks[0], toks[1]);
        _assertKeyEq(returned, key);
        assertTrue(init.isPairPoolLive(toks[0], toks[1]));
    }

    function test_deployPair_skipIfLive_noEvent() public {
        (, IUniswapV4HookStagedPairInit init, address[] memory toks) = _freshBootstrapN(2);
        PoolKey memory first = init.deployPair(toks[0], toks[1]);
        vm.recordLogs();
        PoolKey memory second = init.deployPair(toks[1], toks[0]);
        _assertKeyEq(first, second);
        Vm.Log[] memory logs = vm.getRecordedLogs();
        for (uint256 i; i < logs.length; ++i) {
            assertTrue(logs[i].topics.length == 0 || logs[i].topics[0] != PAIR_POOL_DEPLOYED_TOPIC);
        }
    }

    function test_deployPair_orderIndependent() public {
        (, IUniswapV4HookStagedPairInit init, address[] memory toks) = _freshBootstrapN(3);
        init.deployPair(toks[0], toks[2]);
        init.deployPair(toks[1], toks[2]);
        init.deployPair(toks[0], toks[1]);
        assertTrue(init.isPairPoolLive(toks[0], toks[1]));
        assertTrue(init.isPairPoolLive(toks[1], toks[2]));
        assertTrue(init.isPairPoolLive(toks[0], toks[2]));
    }

    function test_deployPair_reverseArgs_sameDoor() public {
        (, IUniswapV4HookStagedPairInit init, address[] memory toks) = _freshBootstrapN(2);
        PoolKey memory ab = init.deployPair(toks[0], toks[1]);
        PoolKey memory ba = init.pairPoolKey(toks[1], toks[0]);
        _assertKeyEq(ab, ba);
        assertTrue(init.isPairPoolLive(toks[1], toks[0]));
    }

    function test_deployPair_unboundOrSameTokenReverts() public {
        (, IUniswapV4HookStagedPairInit init, address[] memory toks) = _freshBootstrapN(2);
        vm.expectRevert(UniswapV4StandardExchangeWeightedBufferHookTarget.InvalidPair.selector);
        init.deployPair(toks[0], toks[0]);
        vm.expectRevert(UniswapV4StandardExchangeWeightedBufferHookTarget.InvalidPair.selector);
        init.deployPair(toks[0], address(0xB0B0));
        vm.expectRevert(UniswapV4StandardExchangeWeightedBufferHookTarget.InvalidPair.selector);
        init.deployPair(address(0), toks[0]);
    }

    function test_finalize_revertsMissingOneOfCn2() public {
        (, IUniswapV4HookStagedPairInit init, address[] memory toks) = _freshBootstrapN(3);
        vm.expectRevert(IUniswapV4HookStagedPairInit.ProductDoorsNotLive.selector);
        init.finalizeInitialization();

        init.deployPair(toks[0], toks[1]);
        init.deployPair(toks[1], toks[2]);
        vm.expectRevert(IUniswapV4HookStagedPairInit.ProductDoorsNotLive.selector);
        init.finalizeInitialization();
    }

    function test_n2_onePair_finalize() public {
        (address h, IUniswapV4HookStagedPairInit init, address[] memory toks) = _freshBootstrapN(2);
        init.deployPair(toks[0], toks[1]);
        IDiamond.FacetCut[] memory cuts = _expectedFinalizeCuts();
        vm.expectEmit(false, false, false, true, h);
        emit IDiamond.DiamondCut(cuts, address(0), "");
        vm.expectEmit(true, false, false, true, h);
        emit IUniswapV4HookStagedPairInit.InitializationFinalized(h);
        assertTrue(init.finalizeInitialization());
