            token1: address(b),
            token2: address(c),
            decimals0: HookPkgArgsDecimalsLib.tokenDec(address(a)),
            decimals1: HookPkgArgsDecimalsLib.tokenDec(address(b)),
            decimals2: HookPkgArgsDecimalsLib.tokenDec(address(c)),
            se0: se,
            se1: address(0),
            se2: address(0),
            rp0: address(0),
            rp1: address(0),
